MODEL_COUNT = 5626


def normalize_model_name(name: str) -> str:
    """Normalize model name for pricing lookup."""
    n = name.strip().lower()
    for prefix in ("openrouter/", "azure/", "bedrock/"):
        if n.startswith(prefix):
            n = n[len(prefix) :]
    return n


def calculate_cost(
    model: str,
    input_tokens: int,
    output_tokens: int,
    cached_tokens: int = 0,
    reasoning_tokens: int = 0,
) -> dict[str, float]:
    """Calculate USD cost for a model call based on token usage."""
    normalized = normalize_model_name(model)
    rates = PRICING.get(model) or PRICING.get(normalized) or PRICING.get(normalized.lower())
    if not rates:
        return {}
    cacheable_input = max(0, input_tokens - cached_tokens)
    input_cost = cacheable_input * rates.get("input", 0)
    output_cost = output_tokens * rates.get("output", 0)
    cache_read_cost = cached_tokens * rates.get("cache_read", 0)
    reasoning_cost = reasoning_tokens * rates.get("reasoning", 0)
    total = input_cost + output_cost + cache_read_cost + reasoning_cost
    return {
        "input_cost": round(input_cost + cache_read_cost, 8),
        "output_cost": round(output_cost + reasoning_cost, 8),
        "total_cost": round(total, 8),
    }
